<script setup lang="ts">
import { AlertTriangle, Box, Building2, Check, Clock3, ContactRound, RefreshCw, RotateCcw, Search, ShieldAlert, Trash2, Users, X } from '@lucide/vue';
const config = useRuntimeConfig();
const { token } = useWorkspaceSession();
const entries = ref<any[]>([]);
const selected = ref<any>(null);
const preview = ref<any>(null);
const type = ref('');
const search = ref('');
const busy = ref(false);
const error = ref('');
const notice = ref('');
const confirmation = ref('');
const adminPassword = ref('');
let timer: ReturnType<typeof setTimeout>|undefined;
const headers = computed(()=>({Authorization:`Bearer ${token.value}`}));
const types = [{id:'',label:'Все данные',icon:Trash2},{id:'USER',label:'Учётные записи',icon:ContactRound},{id:'CUSTOMER',label:'Клиенты',icon:Users},{id:'ORGANIZATION',label:'Организации',icon:Building2},{id:'PRODUCT',label:'Товары',icon:Box},{id:'CATEGORY',label:'Категории',icon:Box}];
const typeLabels:Record<string,string>={USER:'Учётная запись',CUSTOMER:'Клиент',ORGANIZATION:'Организация B2B',PRODUCT:'Товар',CATEGORY:'Категория'};
async function load(){busy.value=true;error.value='';try{const result=await $fetch<any>('/data-lifecycle/trash',{baseURL:config.public.apiBase,headers:headers.value,query:{type:type.value||undefined,search:search.value||undefined}});entries.value=result.items}catch(exception:any){error.value=messageOf(exception)}finally{busy.value=false}}
async function openEntry(entry:any){selected.value=entry;confirmation.value='';adminPassword.value='';preview.value=null;error.value='';try{preview.value=await $fetch(`/data-lifecycle/${entry.entityType}/${entry.entityId}/preview`,{baseURL:config.public.apiBase,headers:headers.value})}catch(exception:any){error.value=messageOf(exception)}}
async function restore(){if(!selected.value)return;await act(async()=>{await $fetch(`/data-lifecycle/trash/${selected.value.id}/restore`,{baseURL:config.public.apiBase,method:'POST',headers:headers.value});selected.value=null;await load();showNotice('Данные восстановлены')})}
async function purge(){if(!selected.value)return;await act(async()=>{await $fetch(`/data-lifecycle/trash/${selected.value.id}`,{baseURL:config.public.apiBase,method:'DELETE',headers:headers.value,body:{confirmation:confirmation.value,currentAdminPassword:adminPassword.value}});selected.value=null;await load();showNotice('Данные окончательно удалены')})}
async function act(callback:()=>Promise<void>){busy.value=true;error.value='';try{await callback()}catch(exception:any){error.value=messageOf(exception)}finally{busy.value=false}}
function messageOf(exception:any){return exception?.data?.message||exception?.message||'Не удалось выполнить действие'}
function showNotice(value:string){notice.value=value;setTimeout(()=>notice.value='',2600)}
function daysLeft(value:string){return Math.max(0,Math.ceil((new Date(value).getTime()-Date.now())/86400000))}
watch(type,load);watch(search,()=>{if(timer)clearTimeout(timer);timer=setTimeout(load,350)});onMounted(load);
</script>

<template><section data-v-ui-fb6b400b9590 class="trash-workspace"><aside data-v-ui-fb6b400b9590 class="trash-types"><header data-v-ui-fb6b400b9590><p data-v-ui-fb6b400b9590>ФИЛЬТР</p><h2 data-v-ui-fb6b400b9590>Тип данных</h2></header><button data-v-ui-fb6b400b9590 v-for="item in types" :key="item.id" :class="{active:type===item.id}" @click="type=item.id"><component data-v-ui-fb6b400b9590 :is="item.icon" :size="16"/><span data-v-ui-fb6b400b9590>{{item.label}}</span><b data-v-ui-fb6b400b9590>{{item.id?entries.filter(row=>row.entityType===item.id).length:entries.length}}</b></button><div data-v-ui-fb6b400b9590 class="retention"><Clock3 data-v-ui-fb6b400b9590 :size="18"/><span data-v-ui-fb6b400b9590><strong data-v-ui-fb6b400b9590>Хранение 30 дней</strong><small data-v-ui-fb6b400b9590>До окончательного удаления объект можно восстановить вместе с его состоянием.</small></span></div></aside><main data-v-ui-fb6b400b9590 class="trash-card"><header data-v-ui-fb6b400b9590><div data-v-ui-fb6b400b9590><p data-v-ui-fb6b400b9590>БЕЗОПАСНОЕ УДАЛЕНИЕ</p><h2 data-v-ui-fb6b400b9590>Объекты в корзине</h2><span data-v-ui-fb6b400b9590>{{entries.length}} объектов ожидают решения</span></div><div data-v-ui-fb6b400b9590 class="actions"><label data-v-ui-fb6b400b9590><Search data-v-ui-fb6b400b9590 :size="16"/><input data-v-ui-fb6b400b9590 v-model.trim="search" placeholder="Поиск по названию"/></label><button data-v-ui-fb6b400b9590 title="Обновить" @click="load"><RefreshCw data-v-ui-fb6b400b9590 :size="16" :class="{spin:busy}"/></button></div></header><div data-v-ui-fb6b400b9590 class="trash-table"><div data-v-ui-fb6b400b9590 class="trash-row head"><span data-v-ui-fb6b400b9590>Объект</span><span data-v-ui-fb6b400b9590>Тип</span><span data-v-ui-fb6b400b9590>Удалил</span><span data-v-ui-fb6b400b9590>Осталось</span><span data-v-ui-fb6b400b9590></span></div><button data-v-ui-fb6b400b9590 v-for="entry in entries" :key="entry.id" class="trash-row" @click="openEntry(entry)"><span data-v-ui-fb6b400b9590><i data-v-ui-fb6b400b9590><component data-v-ui-fb6b400b9590 :is="types.find(item=>item.id===entry.entityType)?.icon||Trash2" :size="16"/></i><span data-v-ui-fb6b400b9590><strong data-v-ui-fb6b400b9590>{{entry.displayName}}</strong><small data-v-ui-fb6b400b9590>{{entry.reason||'Причина не указана'}}</small></span></span><span data-v-ui-fb6b400b9590>{{typeLabels[entry.entityType]||entry.entityType}}</span><span data-v-ui-fb6b400b9590>{{[entry.actor?.firstName,entry.actor?.lastName].filter(Boolean).join(' ')||entry.actor?.email||'Система'}}</span><span data-v-ui-fb6b400b9590><b data-v-ui-fb6b400b9590>{{daysLeft(entry.purgeAfter)}}</b> дн.</span><RotateCcw data-v-ui-fb6b400b9590 :size="16"/></button><div data-v-ui-fb6b400b9590 v-if="!entries.length&&!busy" class="empty"><Trash2 data-v-ui-fb6b400b9590 :size="30"/><strong data-v-ui-fb6b400b9590>Корзина пуста</strong><span data-v-ui-fb6b400b9590>Удалённые объекты появятся здесь и будут доступны для восстановления.</span></div></div></main><Teleport to="body"><div data-v-ui-fb6b400b9590 v-if="selected" class="trash-backdrop admin-dialog-backdrop" @mousedown.self="selected=null"><aside data-v-ui-fb6b400b9590 class="trash-drawer admin-dialog admin-dialog--drawer"><header data-v-ui-fb6b400b9590><div data-v-ui-fb6b400b9590><p data-v-ui-fb6b400b9590>{{typeLabels[selected.entityType]}}</p><h2 data-v-ui-fb6b400b9590>{{selected.displayName}}</h2><span data-v-ui-fb6b400b9590>В корзине с {{new Date(selected.trashedAt).toLocaleString('ru-RU')}}</span></div><button data-v-ui-fb6b400b9590 @click="selected=null"><X data-v-ui-fb6b400b9590 :size="19"/></button></header><div data-v-ui-fb6b400b9590 class="drawer-body admin-dialog-body"><section data-v-ui-fb6b400b9590 class="restore-block"><RotateCcw data-v-ui-fb6b400b9590 :size="22"/><div data-v-ui-fb6b400b9590><h3 data-v-ui-fb6b400b9590>Объект можно восстановить</h3><p data-v-ui-fb6b400b9590>Будет возвращено состояние, которое было до перемещения в корзину.</p></div><button data-v-ui-fb6b400b9590 @click="restore">Восстановить</button></section><section data-v-ui-fb6b400b9590><div data-v-ui-fb6b400b9590 class="section-title"><div data-v-ui-fb6b400b9590><h3 data-v-ui-fb6b400b9590>Связи и последствия</h3><p data-v-ui-fb6b400b9590>Финансовая и операционная история защищена от каскадного удаления.</p></div><ShieldAlert data-v-ui-fb6b400b9590 :size="19"/></div><div data-v-ui-fb6b400b9590 v-if="preview" class="dependencies"><article data-v-ui-fb6b400b9590 v-for="dependency in preview.dependencies" :key="dependency.key" :class="{blocking:dependency.blocking&&dependency.count}"><span data-v-ui-fb6b400b9590>{{dependency.label}}</span><b data-v-ui-fb6b400b9590>{{dependency.count}}</b><small data-v-ui-fb6b400b9590>{{dependency.blocking&&dependency.count?'блокирует удаление':'не блокирует'}}</small></article></div></section><section data-v-ui-fb6b400b9590 class="danger-zone"><div data-v-ui-fb6b400b9590 class="section-title"><div data-v-ui-fb6b400b9590><h3 data-v-ui-fb6b400b9590>Окончательное удаление</h3><p data-v-ui-fb6b400b9590>Действие нельзя отменить. Снимок персональных данных также будет очищен.</p></div><AlertTriangle data-v-ui-fb6b400b9590 :size="19"/></div><div data-v-ui-fb6b400b9590 v-if="preview&&!preview.canPurge" class="blocked"><ShieldAlert data-v-ui-fb6b400b9590 :size="17"/><span data-v-ui-fb6b400b9590><strong data-v-ui-fb6b400b9590>Удаление сейчас запрещено</strong><small data-v-ui-fb6b400b9590>Сначала обработайте перечисленные выше связанные данные.</small></span></div><template v-else><label data-v-ui-fb6b400b9590><span data-v-ui-fb6b400b9590>Введите точно: <b data-v-ui-fb6b400b9590>{{selected.displayName}}</b></span><input data-v-ui-fb6b400b9590 v-model="confirmation"/></label><label data-v-ui-fb6b400b9590><span data-v-ui-fb6b400b9590>Пароль администратора</span><input data-v-ui-fb6b400b9590 v-model="adminPassword" type="password" autocomplete="current-password"/></label><button data-v-ui-fb6b400b9590 class="purge" :disabled="confirmation!==selected.displayName||!adminPassword||busy" @click="purge"><Trash2 data-v-ui-fb6b400b9590 :size="16"/>Удалить без возможности восстановления</button></template></section></div></aside></div></Teleport><p data-v-ui-fb6b400b9590 v-if="error" class="trash-error">{{error}}</p><p data-v-ui-fb6b400b9590 v-if="notice" class="trash-notice"><Check data-v-ui-fb6b400b9590 :size="15"/>{{notice}}</p></section></template>


